import{_ as a,b as e,c as d,I as r}from"./chunks/framework.C6cPs9Ia.js";const h=JSON.parse('{"title":"2026 夏季新番扫雷报告","description":"2026 年 7 月新番扫雷总结，一个高中生的追番台账","frontmatter":{"title":"2026 夏季新番扫雷报告","date":"2026-09-06T00:00:00.000Z","tags":["动画","追番"],"cover":"/LQY/wallpaper-2311325.webp","head":[["meta",{"name":"description","content":"2026 年 7 月新番扫雷总结，一个高中生的追番台账"}],["meta",{"name":"keywords","content":"2026夏番, 新番, 追番, 动画推荐"}]]},"headers":[],"relativePath":"posts/anime-summer.md","filePath":"posts/anime-summer.md"}'),l={name:"posts/anime-summer.md"};function i(s,t,o,n,m,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<p>七月番全部收官！本季共试看 14 部、坚持追完 7 部、弃番 7 部，把这份扫雷台账整理出来给想补番的同学。</p><hr><h2 id="本季结论先行" tabindex="-1">本季结论先行 <a class="header-anchor" href="#本季结论先行" aria-label="Permalink to &quot;本季结论先行&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">本季黑马</p><p>《放学后的天文部·二期》——第一季默默无闻，第二季直接起飞。作画肉眼可见地涨预算，星空场景每一帧都能截图当壁纸。</p></div><div class="danger custom-block"><p class="custom-block-title">本季雷区</p><p>某部原作党期待值拉满的续作，首集就开始魔改，第三集直接原创剧情起飞。<strong>建议原作党绕道，动画党当全新作品看还行。</strong></p></div><h2 id="追完的七部-个人向评分" tabindex="-1">追完的七部（个人向评分） <a class="header-anchor" href="#追完的七部-个人向评分" aria-label="Permalink to &quot;追完的七部（个人向评分）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作品</th><th>评分</th><th>一句话点评</th></tr></thead><tbody><tr><td>放学后的天文部·二期</td><td>9.2</td><td>本季最佳，星空作画封神</td></tr><tr><td>深夜咖啡屋物语</td><td>8.8</td><td>治愈系天花板，适合写完作业看</td></tr><tr><td>机关宅邸的机器人小姐</td><td>8.5</td><td>温柔的科幻，ED 每集都在换</td></tr><tr><td>竞技叠杯少女</td><td>8.0</td><td>冷门运动番，热血程度意外地高</td></tr><tr><td>名侦探的暑假</td><td>7.8</td><td>单元剧结构舒服，适合下饭</td></tr><tr><td>魔法少女不再魔法</td><td>7.5</td><td>设定有趣但节奏后半段崩了</td></tr><tr><td>剑与魔法的第一课</td><td>7.0</td><td>及格的异世界教科书</td></tr></tbody></table><h2 id="弃番理由公开处刑" tabindex="-1">弃番理由公开处刑 <a class="header-anchor" href="#弃番理由公开处刑" aria-label="Permalink to &quot;弃番理由公开处刑&quot;">​</a></h2><details><summary>第一集就弃（3 部）</summary><ul><li>三部都是&quot;开头十分钟讲设定，我一个没记住&quot;的类型</li><li>现在的新番流行把世界观做成说明书塞首集，真的会困</li></ul></details><details><summary>追到一半弃（4 部）</summary><ul><li>两部是因为更新时间太阴间，档期冲突</li><li>一部是主角团吵架吵了三集没吵完</li><li>一部纯粹是我忘了追（对不起）</li></ul></details><h2 id="下季预习" tabindex="-1">下季预习 <a class="header-anchor" href="#下季预习" aria-label="Permalink to &quot;下季预习&quot;">​</a></h2><p>十月番的 PV 我已经刷完一轮，重点关注：</p><ol><li><strong>某游戏改编作</strong>——原作是本命游戏，PV 里的角色还原度让我放心了一半</li><li>续作两部和一部剧场版补充篇</li><li>冷门原创一部——原创番是赌博，但原创番出神作的概率也最高</li></ol><p>那就这样，十月见。在那之前，先把 9 月的月考解决掉（这个月第二遍说这句话了）。</p>',14)])])}const u=a(l,[["render",i]]);export{h as __pageData,u as default};
